// O node HTTP Request de multipart do n8n usa o nome do CAMPO binário como
// nome de arquivo no multipart -- Gotenberg exige que o arquivo principal se
// chame exatamente "index.html". Preparamos o binário aqui com esse nome
// antes de chamar o Gotenberg.
const item = $input.first();
const buffer = Buffer.from(item.json.html, 'utf-8');
return [{
  json: item.json,
  binary: {
    report_html: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
    },
  },
}];

// Troca o nome do arquivo (o Gotenberg retorna um UUID.pdf generico) pelo
// nome real que o cliente ve no anexo do e-mail.
const item = $input.first();
const cfg = $('Configuração').first().json;
const monthLabel = item.json.month_label || '';
const safeClient = cfg.client_name.replace(/[\\/:*?"<>|]/g, '').trim();
const fileName = `${safeClient} - ${monthLabel}.pdf`;
item.binary.report_pdf.fileName = fileName;
return [item];
